/**
 * Call-level circuit breaker for identical consecutive tool calls.
 *
 * The existing cross-turn `ToolCallLoopGuard` (see
 * `@oh-my-pi/pi-ai/utils/tool-call-loop-guard`) hashes the whole *set* of tool
 * calls per assistant turn and injects an advisory steer exactly once per
 * streak. In practice that misses the failure mode it was built for:
 * interleaved repeats (read A, read B, read A, read B, ...) never accumulate a
 * turn-set streak, within-turn repeats are invisible to it, and a model that
 * ignores the single advisory steer loops forever with no escalation.
 *
 * This breaker runs per tool *call* — inside `AgentSession.#beforeToolCall` /
 * `#afterToolCall`, which see every dispatched call in order regardless of how
 * turns are packaged. Consecutive identical calls (same tool, same canonical
 * arguments) earn a warning at 3 and a hard block at 5. The block is enforced,
 * not suggested: the call never executes and the model gets the reason as its
 * tool result. Any different call resets the streak.
 *
 * One breaker instance per `AgentSession` (i.e. per agent, main or subagent).
 */

const CONSECUTIVE_WARN_THRESHOLD = 3;
const CONSECUTIVE_BLOCK_THRESHOLD = 5;
/** Past this streak the block message escalates: stop and report, not retry. */
const CONSECUTIVE_ESCALATED_BLOCK_THRESHOLD = 8;

/** Canonicalize a value for fingerprinting: sorted keys, recursive. */
function canonicalize(value: unknown): unknown {
	if (Array.isArray(value)) return value.map(canonicalize);
	if (!value || typeof value !== "object") return value;
	const input = value as Record<string, unknown>;
	const output: Record<string, unknown> = {};
	for (const key of Object.keys(input).sort()) {
		output[key] = canonicalize(input[key]);
	}
	return output;
}

function fingerprint(toolName: string, args: unknown): string {
	try {
		return `${toolName}::${JSON.stringify(canonicalize(args))}`;
	} catch {
		return `${toolName}::${String(args)}`;
	}
}

export type CircuitBreakerAction = "allow" | "warn" | "block";

export interface CircuitBreakerVerdict {
	action: CircuitBreakerAction;
	/** Length of the current consecutive-identical streak (this call included). */
	streak: number;
	/** Human-readable note for warn/block verdicts. */
	message?: string;
}

function warnMessage(toolName: string, streak: number): string {
	return (
		`[circuit breaker] You have called \`${toolName}\` with identical arguments ${streak} times in a row. ` +
		`The results are not changing. Re-read your earlier results above, change your approach, ` +
		`or stop and report what is blocking you — do not keep repeating this call.`
	);
}

