  pattern: string;
  paths?: string[];
  maxLines?: number;
  timeoutMs?: number;
}

export function safeSearch(options: SafeSearchOptions): {
  stdout: string;
  stderr: string;
  exitCode: number;
} {
  const {
    pattern,
    paths = [ … ],
    maxLines = 100,
    timeoutMs = 5000,
