  const args: string[] = [ … ];

  for (const glob of defaultExcludes) {
    args.push("-g", glob);
  }

  args.push("-e", pattern, "--", ...paths);

  const proc = spawnSync("rg", args, { … });

  const lines = (proc.stdout || "").split("\n");
